wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

const SYSTEM: &str = "You are a customer support agent. Answer the user's \
    question using the provided knowledge. You may call the `lookup` tool to \
    search the knowledge base for anything you are missing. When you have \
    enough information, reply with the final answer as plain text.";

const MAX_ROUNDS: usize = 8;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // `requires len(question) <= 512` is a precondition guaranteed by the
        // caller; the node assumes it and does not re-check.

        let mut prompt = String::new();
        prompt.push_str("Intent: ");
        prompt.push_str(intent_label(ctx.intent));
        prompt.push('\n');

        if !ctx.knowledge.is_empty() {
            prompt.push_str("Knowledge:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }

        prompt.push_str("Question: ");
        prompt.push_str(&ctx.question);
        prompt.push('\n');

        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(SYSTEM, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    // The only tool in this node's scope is `lookup`, backed by
                    // the read-only knowledge-base handle.
                    let results = kb_read::lookup(&req.query);

                    prompt.push_str("\nTool `");
                    prompt.push_str(&req.tool);
                    prompt.push_str("` results for \"");
                    prompt.push_str(&req.query);
                    prompt.push_str("\":\n");
                    if results.is_empty() {
                        prompt.push_str("(no results)\n");
                    } else {
                        for r in &results {
                            prompt.push_str("- ");
                            prompt.push_str(r);
                            prompt.push('\n');
                        }
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-orchestration loop did not converge".to_string(),
        })
    }
}

export!(Node);
```

